 if(transport==='ai'&&aiConfiguration?.configured){const model=q('[data-control=model]');const label=model.querySelector('span span')||model.querySelector('span');label.textContent=aiConfiguration.model.replace(/^gemini-/,'Gemini ').replace(/-flash$/,' Flash');model.title='Model comes from the server configuration';}const sidebar=root.querySelector('[data-shrink]');sidebar.insertAdjacentHTML('beforeend',`<button class="session-profile" data-onboard><span>${safe(name.slice(0,1).toUpperCase())}</span>${safe(name)}</button>`);const history=sidebar.querySelector('ol');
 const renderHistory=(kind=isCharacter?'character':'story')=>{if(!history)return;const ids=[id,...h.data.filter(t=>h.read('ooc-session-v2-'+t.id,[]).length>0).map(t=>t.id)].filter((value,index,all)=>all.indexOf(value)===index).filter(storyId=>((h.data.find(t=>t.id===storyId)||title).type==='character'?'character':'story')===kind);history.innerHTML=ids.length?ids.slice(0,12).map(storyId=>{const item=h.data.find(t=>t.id===storyId)||title;const last=h.read('ooc-session-v2-'+storyId,[]).findLast(m=>m.text&&!m.failed);return `<li class="session-history-item"><a href="/play/${safe(storyId)}" ${storyId===id?'aria-current="page"':''}><img src="${safe(item.image?.startsWith('assets/')?'/'+item.image:item.image||'')}" alt=""><span><strong>${safe(item.title)}</strong><small>${safe(last?.text?.replace(/[*#>\n]/g,' ').slice(0,85)||'Start your story')}</small></span></a></li>`;}).join(''):'<li class="session-history-empty">Your recent sessions will appear here.</li>';sidebar.querySelectorAll('button').forEach(button=>{if(['Story','Character'].includes(button.textContent.trim()))button.setAttribute('aria-pressed',String(button.textContent.trim().toLowerCase()===kind));});};renderHistory();
 sidebar.querySelectorAll('button').forEach(button=>{const label=button.textContent.trim();if(['Story','Character'].includes(label))button.onclick=()=>renderHistory(label.toLowerCase());if(label==='Search')button.onclick=()=>h.navigate('/search');if(label==='Notifications')button.onclick=()=>modal('Notifications','<p>No new notifications.</p>');});
  const toggleSidebar=()=>{const small=sidebar.dataset.shrink!=='true';sidebar.dataset.shrink=String(small);sidebar.nextElementSibling.style.marginLeft=matchMedia('(min-width:1024px)').matches?(small?'48px':'256px'):'';};if(sidebar)sidebar.querySelector('button').onclick=toggleSidebar;const settingsToggle=q('[data-control=settings]');
 const showSettings=()=>{const open=settings.classList.toggle('session-open');settings.inert=!open;settingsToggle?.setAttribute('aria-expanded',String(open));if(open&&matchMedia('(max-width:767px)').matches)settings.querySelector('button')?.focus();};settings.inert=true;settingsToggle?.setAttribute('aria-controls','session-settings');settingsToggle?.setAttribute('aria-expanded','false');
